    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 82-year-old female named Pamela presents to the bedside monitor area with fever, acute confusion, and dyspnea. Physical examination reveals multiple petechiae on the oral mucosa, a new early diastolic murmur, and splinter hemorrhages under the fingernails. Blood cultures are drawn. What is the most appropriate empiric antimicrobial regimen while awaiting culture results?', '["Oral Amoxicillin and Clindamycin", "Intravenous Piperacillin-Tazobactam as monotherapy", "Intravenous Vancomycin and Ceftriaxone", "Intravenous Azithromycin and Ciprofloxacin", "Intravenous Acyclovir and Ganciclovir"]'::jsonb, 2, 'The clinical presentation is highly suggestive of acute infective endocarditis. Empiric antibiotic therapy must be initiated promptly in patients with suspected IE who are acutely ill or hemodynamically unstable, after drawing at least 2-3 sets of blood cultures. The standard empiric regimen for acute IE (targeting MRSA, streptococci, and enterococci) consists of intravenous Vancomycin to cover Gram-positives including resistant strains, combined with intravenous Ceftriaxone (2 g every 12 hours) or Gentamicin. (Ref: Tintinalli''s Ch. 55; Step-Up to EM Ch. 2; Case Files: EM Case 5)'),
    (v_topic_id, 'A 62-year-old male named Joshua presents to the bedside monitor area with fever, acute confusion, and dyspnea. Physical examination reveals multiple petechiae on the oral mucosa, a new early diastolic murmur, and splinter hemorrhages under the fingernails. Blood cultures are drawn. What is the most appropriate empiric antimicrobial regimen while awaiting culture results?', '["Intravenous Azithromycin and Ciprofloxacin", "Intravenous Vancomycin and Ceftriaxone", "Oral Amoxicillin and Clindamycin", "Intravenous Acyclovir and Ganciclovir", "Intravenous Piperacillin-Tazobactam as monotherapy"]'::jsonb, 1, 'The clinical presentation is highly suggestive of acute infective endocarditis. Empiric antibiotic therapy must be initiated promptly in patients with suspected IE who are acutely ill or hemodynamically unstable, after drawing at least 2-3 sets of blood cultures. The standard empiric regimen for acute IE (targeting MRSA, streptococci, and enterococci) consists of intravenous Vancomycin to cover Gram-positives including resistant strains, combined with intravenous Ceftriaxone (2 g every 12 hours) or Gentamicin. (Ref: Tintinalli''s Ch. 55; Step-Up to EM Ch. 2; Case Files: EM Case 5)'),
